def choose_move(observation):
    def sgn(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos2(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [sgn(dst[0] - src[0]), sgn(dst[1] - src[1])]

    def best_by(items, keyfunc):
        try:
            return min(items, key=keyfunc)
        except Exception:
            return None

    sx_sy = pos2(observation.get("self_position"))
    ox_oy = pos2(observation.get("opponent_position"))
    if sx_sy is None:
        return [0, 0]
    sx, sy = sx_sy
    ox, oy = ox_oy if ox_oy is not None else sx_sy

    env = observation.get("environment_name", "resource_collection")

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)

        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))

        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

        target = best_by(corners, lambda c: dist(c, (ox, oy)))
        if target is None:
            return [0, 0]
        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        if targets:
            target = best_by(targets, lambda p: dist(pos2(p) if pos2(p) is not None else (sx, sy), (sx, sy)))
            tp = pos2(target)
            if tp is not None:
                return step_toward((sx, sy), tp)
        # fallback: drift toward opponent to contest
        return step_toward((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    if resources:
        target = best_by(resources, lambda p: dist(pos2(p) if pos2(p) is not None else (sx, sy), (sx, sy)))
        tp = pos2(target)
        if tp is not None:
            return step_toward((sx, sy), tp)

    # general fallback: chase or hold centerward if opponent missing
    if ox_oy is not None:
        return step_toward((sx, sy), (ox, oy))
    return [0, 0]

